INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63247930', 63247930, 'analyze_legacy', 'Badan Narkotika Nasional', 'central', 'BADAN NARKOTIKA NASIONAL KABUPATEN SIDOARJO', 'Bundling Teskit Narkoba 7P', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 139200000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Kegiatan pengadaan ini meliputi penyediaan tes kit narkoba 7 parameter (7P) yang dibundel dengan perlengkapan pendukung berupa masker, handscone (sarung tangan medis), pH meter/strip pH, dan pot urine, yang digunakan untuk pelaksanaan layanan pemeriksaan narkoba sebanyak 600 layanan. Pengadaan bertujuan untuk mendukung kegiatan layanan tes urine secara aman, akurat, higienis, dan sesuai standar operasional yang berlaku.', 'Spesifikasi Teknis Tes Kit Narkoba 7 Parameter (7P) Jenis alat: Rapid Test Narkoba Multi Parameter (7 Panel). Metode pemeriksaan: Immunochromatographic assay (screening test). Sampel: Urine. Parameter yang diuji minimal meliputi 7 jenis narkotika/psikotropika, antara lain: Amphetamine (AMP) Methamphetamine (MET) Marijuana/THC Cocaine (COC) Opiate/Morphine (OPI/MOP) Benzodiazepine (BZD) SOMA/Carisoprodol Waktu pembacaan hasil: maksimal 5 menit. Tampilan hasil: garis indikator visual yang jelas (positif/negatif/invalid). Penyimpanan: suhu ruang sesuai petunjuk pabrik. Dilengkapi petunjuk penggunaan dalam Bahasa Indonesia. 4. Spesifikasi Teknis Perlengkapan Bundling A. Masker Jenis: masker medis sekali pakai. Bahan: non-woven, minimal 3 ply. Fungsi: perlindungan petugas dan klien selama layanan tes urine. Jumlah: 1 masker per layanan (total minimal 600 buah). B. Handscone (Sarung Tangan Medis) Jenis: sarung tangan medis sekali pakai (latex atau nitrile). Ukuran: menyesuaikan kebutuhan petugas. Steril/tidak steril sesuai standar pemeriksaan. Jumlah: minimal 1 pasang per layanan (total minimal 600 pasang). C. pH Meter / Strip pH Urine Jenis: strip pH atau alat ukur pH urine sekali pakai. Rentang pengukuran: minimal pH 4–9. Akurasi: sesuai standar pemeriksaan urine. Fungsi: memastikan keabsahan sampel urine. Jumlah: 1 unit per layanan (total minimal 600 unit). D. Pot Urine Bahan: plastik transparan berkualitas medis. Kapasitas: ±30–60 ml. Dilengkapi tutup ulir yang rapat dan tidak bocor. Steril atau bersih sesuai standar layanan tes urine. Sekali pakai. Jumlah: 1 pot per layanan (total minimal 600 buah). 5. Volume Pekerjaan Jumlah layanan: 600 layanan. Setiap 1 layanan terdiri dari: 1 tes kit narkoba 7P, 1 masker, 1 pasang handscone, 1 pH meter/strip pH, dan 1 pot urine.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 792399);
